-- Generated by tools/gen_npcs.py: edit the table there, not this file.
local npcName = "Runewright Mael"
local npcType = Game.createNpcType(npcName)
local npcConfig = {}
npcConfig.name = npcName
npcConfig.description = "the runewright"
npcConfig.health = 100
npcConfig.maxHealth = npcConfig.health
npcConfig.walkInterval = 2000
npcConfig.walkRadius = 1  -- NPCs only listen within 3 tiles: 1 behind a counter + 1 step keeps a player at the counter in earshot
npcConfig.outfit = { lookType = 2027, lookHead = 0, lookBody = 0, lookLegs = 0, lookFeet = 0, lookAddons = 0 }
npcConfig.flags = { floorchange = false }
npcConfig.voices = {
	interval = 45000, -- G12b: about once every 3 minutes, like the townsfolk (was every 30-50 s: the Hearth never went quiet)
	chance = 25,
	{ text = "Blank runes! Ready for your spells!" },
}
npcConfig.shop = {
	{ itemName = "blank rune", clientId = 3147, buy = 10 },
	{ itemName = "wand of vortex", clientId = 3074, buy = 500, sell = 100 },
	{ itemName = "snakebite rod", clientId = 3066, buy = 500, sell = 100 },
	{ itemName = "amber waycrystal (floor 1)", clientId = 3251, buy = 150 },
}

local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
npcType.onThink = function(npc, interval) npcHandler:onThink(npc, interval) end
npcType.onAppear = function(npc, creature) npcHandler:onAppear(npc, creature) end
npcType.onDisappear = function(npc, creature) npcHandler:onDisappear(npc, creature) end
npcType.onMove = function(npc, creature, from, to) npcHandler:onMove(npc, creature, from, to) end
npcType.onSay = function(npc, creature, type, message) npcHandler:onSay(npc, creature, type, message) end
npcType.onCloseChannel = function(npc, player) npcHandler:onCloseChannel(npc, player) end
npcType.onBuyItem = function(npc, player, itemId, subType, amount, ignore, inBackpacks, totalCost)
	-- Party playtest 2026-11-26 (hand-off P1-2): with "ignore capacity" ticked the engine took the gold and the item
	-- vanished, so the tick is never passed on; a purchase too heavy to carry is refused in words instead.
	local it = ItemType(itemId)
	if it and it:getWeight(amount) > player:getFreeCapacity() then
		player:sendCancelMessage("You can't carry that much. Make room or lighten your load first.")
		return
	end
	npc:sellItem(player, itemId, amount, subType, 0, false, inBackpacks)
end
npcType.onSellItem = function(npc, player, itemId, subtype, amount, ignore, name, totalCost)
	player:sendTextMessage(MESSAGE_TRADE, string.format("Sold %ix %s for %i gold.", amount, name, totalCost))
end
npcType.onCheckItem = function(npc, player, clientId, subType) end

-- Murderers (red/black) get no service in town (DESIGN.md 6.4)
local function refuseMurderers(npc, player)
	if SpirePvP and SpirePvP.isMurderer(player) then
		npcHandler:say("I don't deal with murderers. Get out.", npc, player)
		return false
	end
	return true
end

keywordHandler:addKeyword({ "job" }, StdModule.say, { npcHandler = npcHandler, text = "The runewright. Ask me for a {trade}." })

npcHandler:setMessage(MESSAGE_GREET, "Blank runes for your conjuring, |PLAYERNAME|, made cheaper if you bring gems to {craft} with, and wands and rods for those who need one. Ask for a {trade}.")
npcHandler:setMessage(MESSAGE_FAREWELL, "Good climbing, |PLAYERNAME|.")
npcHandler:setMessage(MESSAGE_WALKAWAY, "Good climbing.")
npcHandler:setCallback(CALLBACK_GREET, refuseMurderers)
npcHandler:setCallback(CALLBACK_MESSAGE_DEFAULT, function(npc, player, type, msg)
	if SpireGear and SpireGear.talk and SpireGear.talk(npc, npcHandler, player, msg, npcConfig.name) then
		return false
	end
	if SpireCraft and SpireCraft.talk(npc, npcHandler, player, msg, npcConfig.name) then
		return false
	end
	if SpireHunt and MsgContains(msg, "hunt") then
		npcHandler:say(SpireHunt.advice(player:getLevel()), npc, player)
		return false
	end
	return true
end)
npcHandler:addModule(FocusModule:new(), npcConfig.name, true, true, true)
npcType:register(npcConfig)
